const raw = $input.first().json;
const input = (raw && raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

const docId = input.document_id || ('doc-' + Date.now());
const versionId = input.version_id || ('ver-' + Date.now());
const docType = input.document_type || 'CLINICAL_REPORT_APPROVED';
const isClinical = input.is_clinical !== false;
const isApproved = input.is_approved === true || input.approval_status === 'APPROVED';
const profCard = input.professional_card || input.professional_card_number;
const isBereaved = Boolean(input.is_bereaved || input.bereavement_protocol_active);
const isCaregiverRevoked = Boolean(input.caregiver_revoked || input.is_caregiver_revoked);
const isCorruptOrInvalid = input.validation_status === 'REJECTED' || input.sha256_corrupt === true;
const isTokenExpired = Boolean(input.is_expired || (input.expires_at && new Date(input.expires_at) < new Date()));

let isEligible = true;
let rejectionReason = null;
let deliveryStatus = 'ACCESS_PREPARED';
let strategy = input.grant_strategy || 'SIGNED_TEMPORARY_URL';

if (isBereaved) {
  isEligible = false;
  rejectionReason = 'SUPPRESSED_BEREAVEMENT_PROTOCOL_ACTIVE';
  deliveryStatus = 'CANCELLED_BEREAVEMENT';
} else if (isCaregiverRevoked) {
  isEligible = false;
  rejectionReason = 'SUPPRESSED_CAREGIVER_PERMISSIONS_REVOKED';
  deliveryStatus = 'REVOKED';
} else if (isCorruptOrInvalid) {
  isEligible = false;
  rejectionReason = 'REJECTED_DOCUMENT_CORRUPT_OR_INVALID';
  deliveryStatus = 'VALIDATION_FAILED';
} else if (isTokenExpired) {
  isEligible = false;
  rejectionReason = 'REJECTED_ACCESS_TOKEN_EXPIRED';
  deliveryStatus = 'EXPIRED';
} else if (!isApproved) {
  isEligible = false;
  rejectionReason = 'REJECTED_UNAPPROVED_DRAFT_DOCUMENT';
  deliveryStatus = 'APPROVAL_PENDING';
} else if (isClinical && (!profCard || String(profCard).trim() === '')) {
  isEligible = false;
  rejectionReason = 'REJECTED_MISSING_LICENSED_VETERINARIAN_SIGN_OFF';
  deliveryStatus = 'APPROVAL_PENDING';
}

const token = 'doc_tok_' + Math.random().toString(36).substring(2, 14);
const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
const storageKey = input.storage_path || ('docs/' + docId + '/v1_document.pdf');
const signedUrl = 'https://sznvahhocgnhsqhksygq.supabase.co/storage/v1/object/sign/medical-records/' + storageKey + '?token=' + token;

return {
  json: {
    document_id: docId,
    version_id: versionId,
    document_type: docType,
    is_clinical: isClinical,
    is_approved: isApproved,
    professional_card: profCard || null,
    authorized_by: input.authorized_by || 'Dr. Luis Eduardo Ríos',
    recipient_id: input.recipient_id || 'rec-default-001',
    recipient_type: input.recipient_type || 'OWNER',
    recipient_name: input.recipient_name || 'Tutor Vet Life',
    recipient_phone: input.recipient_phone || input.client_phone || '+573009988776',
    pet_name: input.pet_name || 'Paciente',
    is_eligible: isEligible,
    rejection_reason: rejectionReason,
    delivery_status: deliveryStatus,
    grant_strategy: strategy,
    access_token: isEligible ? token : null,
    signed_download_url: isEligible ? signedUrl : null,
    expires_at: isEligible ? expiresAt : null,
    delivery_channel: input.delivery_channel || 'WHATSAPP_SANDBOX',
    send_enabled: false,
    evaluated_at: new Date().toISOString()
  }
};
